fn list_deep_clone(arr: &Vec<u64>) -> Vec<u64> {
    // Vec<u64>::clone creates a deep copy of the vector,
    // cloning each element (u64 implements Copy).
    arr.clone()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty() {
        let original: Vec<u64> = Vec::new();
        let cloned = list_deep_clone(&original);
        assert_eq!(original, cloned);
    }

    #[test]
    fn test_non_empty() {
        let original = vec![1, 2, 3, 4, 5];
        let cloned = list_deep_clone(&original);
        assert_eq!(original, cloned);

        // Ensure independence
        // (changing original after clone should not affect `cloned`)
        let mut original_mut = original.clone();
        original_mut.push(6);
        assert_eq!(cloned, vec![1, 2, 3, 4, 5]);
        assert_eq!(original_mut, vec![1, 2, 3, 4, 5, 6]);
    }
}